The move calls have returned, but their effects must be established independently by re-reading the top-level directory, all three destination directories, and every expected destination file.

```python
post_move_root_files = apis.file_system.show_directory(access_token=file_system_access_token, directory_path=vacations_directory, entry_type="files", recursive=False)
expected_names_by_spot = {}
for planned_move in move_plan:
    expected_names_by_spot.setdefault(planned_move["spot"], set()).add(planned_move["filename"])
post_move_entries_by_spot = {}
actual_names_by_spot = {}
for vacation_spot in sorted(expected_names_by_spot):
    destination_entries = apis.file_system.show_directory(access_token=file_system_access_token, directory_path=vacations_directory + vacation_spot + "/", entry_type="files", recursive=False)
    post_move_entries_by_spot[vacation_spot] = destination_entries
    actual_names_by_spot[vacation_spot] = {entry.rstrip("/").rsplit("/", 1)[-1] for entry in destination_entries}
post_move_file_records = []
for planned_move in move_plan:
    destination_details = apis.file_system.show_file(file_path=planned_move["destination"], access_token=file_system_access_token)
    post_move_file_records.append({"plan": planned_move, "details": destination_details})
verification_checks = {
    "no_files_left_at_source_root": len(post_move_root_files) == 0,
    "every_expected_destination_listed": all(expected_names_by_spot[spot].issubset(actual_names_by_spot[spot]) for spot in expected_names_by_spot),
    "every_destination_file_readable": len(post_move_file_records) == len(move_plan),
    "all_original_filenames_maintained": all(item["details"]["path"].rstrip("/").rsplit("/", 1)[-1] == item["plan"]["filename"] for item in post_move_file_records),
    "all_creation_dates_retained": all(str(item["details"]["created_at"]) == item["plan"]["created_at"] for item in post_move_file_records),
}
assert all(verification_checks.values())
verification_summary = {"checks": verification_checks, "verified_file_count": len(post_move_file_records), "verified_by_spot": {spot: len(expected_names_by_spot[spot]) for spot in sorted(expected_names_by_spot)}}
print(verification_summary)
